'use client';

import React, { useState } from 'react';
import { useParams } from 'next/navigation';
import { useLangRouter } from '@/hooks/useLangRouter';
import { ArrowLeft, ChevronDown, PlayCircle } from 'lucide-react';
import { MOCK_SUBJECTS, getSyllabus } from '@/utils/mockData';
import { motion, AnimatePresence } from 'framer-motion';
import T from '@/components/ui/T';

export default function SyllabusPage() {
    const params = useParams();
    const { push } = useLangRouter();

    const curriculumSlug = Array.isArray(params.curriculumSlug) ? params.curriculumSlug[0] : params.curriculumSlug;
    const subjectSlug = Array.isArray(params.subjectSlug) ? params.subjectSlug[0] : params.subjectSlug;

    const allSubjects = MOCK_SUBJECTS[curriculumSlug as keyof typeof MOCK_SUBJECTS] || [];
    const subject = allSubjects.find(s => s.slug === subjectSlug);

    const syllabus = subject ? getSyllabus(subjectSlug, subject.title) : [];
    const [openUnit, setOpenUnit] = useState<number | null>(0);

    if (!subject) {
        return (
            <div className="min-h-screen flex flex-col items-center justify-center bg-[#F2F4F7]">
                <h1 className="text-2xl font-bold mb-4"><T>Subject Not Found</T></h1>
                <button onClick={() => push(`/curriculum/${curriculumSlug}`)} className="text-red-600 font-bold hover:underline"><T>Go Back</T></button>
            </div>
        );
    }

    return (
        <motion.main
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4 }}
            className="min-h-screen bg-[#F2F4F7] font-nunito"
        >

            <div className="container mx-auto px-6 pt-32 pb-20 max-w-4xl">

                {/* Breadcrumb */}
                <button
                    onClick={() => push(`/curriculum/${curriculumSlug}`)}
                    className="flex items-center gap-2 text-gray-500 font-bold hover:text-[#D92D20] mb-8 transition-colors"
                >
                    <ArrowLeft className="w-4 h-4" /> <T>Back to Subjects</T>
                </button>

                {/* Header */}
                <div className="mb-10 text-center md:text-left">
                    <h1 className="text-4xl font-extrabold text-[#101828] mb-2"><T>{subject.title}</T></h1>
                    <div className="flex items-center gap-2 justify-center md:justify-start text-gray-500 font-medium">
                        <span className="bg-white px-3 py-1 rounded-full shadow-sm text-sm border border-gray-100">{curriculumSlug.toUpperCase()}</span>
                        <span>•</span>
                        <span>Code: {subject.code}</span>
                    </div>
                </div>

                {/* ACCORDION STACK */}
                <div className="space-y-4">
                    {syllabus.map((unit, index) => {
                        const isOpen = openUnit === index;

                        return (
                            <motion.div
                                key={index}
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: index * 0.1 }}
                                className="bg-white rounded-[1.5rem] overflow-hidden shadow-sm transition-all"
                            >

                                {/* Clickable Header */}
                                <button
                                    onClick={() => setOpenUnit(isOpen ? null : index)}
                                    className="w-full flex items-center justify-between p-6 hover:bg-gray-50 transition-colors"
                                >
                                    <div className="flex items-center gap-4">
                                        {/* Rotating Icon with Spring Physics */}
                                        <motion.div
                                            animate={{
                                                backgroundColor: isOpen ? '#D92D20' : '#F3F4F6',
                                                color: isOpen ? '#FFFFFF' : '#9CA3AF',
                                                rotate: isOpen ? 180 : 0
                                            }}
                                            transition={{ type: "spring", stiffness: 200, damping: 20 }}
                                            className="w-10 h-10 rounded-xl flex items-center justify-center shadow-sm"
                                        >
                                            <ChevronDown className="w-5 h-5" />
                                        </motion.div>
                                        <h3 className="text-xl font-extrabold text-[#101828]"><T>{unit.title}</T></h3>
                                    </div>
                                    <span className="text-sm font-bold text-gray-400"><T>{unit.topics.length} lessons</T></span>
                                </button>

                                {/* Animated Body */}
                                <AnimatePresence>
                                    {isOpen && (
                                        <motion.div
                                            initial={{ height: 0, opacity: 0 }}
                                            animate={{ height: "auto", opacity: 1 }}
                                            exit={{ height: 0, opacity: 0 }}
                                            transition={{ duration: 0.3, ease: "easeInOut" }}
                                        >
                                            <div className="px-6 pb-6 pt-2">
                                                <div className="space-y-2">
                                                    {unit.topics.map((topic, i) => (
                                                        <motion.div
                                                            key={i}
                                                            initial={{ x: -10, opacity: 0 }}
                                                            animate={{ x: 0, opacity: 1 }}
                                                            transition={{ delay: i * 0.05 }}
                                                            className="group flex items-center justify-between p-4 rounded-xl hover:bg-gray-50 cursor-pointer transition-all border border-transparent hover:border-gray-100"
                                                        >
                                                            <div className="flex items-center gap-4">
                                                                <PlayCircle className="w-5 h-5 text-gray-300 group-hover:text-[#D92D20] transition-colors" />
                                                                <span className="font-bold text-gray-700 group-hover:text-[#101828]"><T>{topic}</T></span>
                                                            </div>
                                                        </motion.div>
                                                    ))}
                                                </div>
                                            </div>
                                        </motion.div>
                                    )}
                                </AnimatePresence>

                            </motion.div>
                        );
                    })}
                </div>

            </div>
        </motion.main>
    );
}
